"""Offline observations remain a distinct product, even before a RESULT exists."""
from typing import Any
from mcp.types import ToolAnnotations
from .observed_match_runs import catalog_runs, ObservedRunQueries

queries=ObservedRunQueries()


def register_observed_match_tools(mcp):
    @mcp.tool(annotations=ToolAnnotations(readOnlyHint=True,destructiveHint=False,openWorldHint=False))
    def fm_list_observed_match_runs() -> dict[str,Any]:
        """Discover approved observed_native_match_run SQLite exports, independently of FM attachment, future RESULT materialization and the last disk save. This distinct source can answer questions about a just-observed match whose retained RESULT is unavailable. Returns exact source_id/capture_id pins, fixture sides/date, captured career/current and last-saved dates, analytical tables/columns, counts and separate terminal shot, passing and earlier spatial-prefix scopes. Never impersonates retained captures or a live current snapshot. Explicit approved originals only; no arbitrary paths or directory scanning. Use fm_query_observed_match_run with the exact catalog pin, then analyze the returned rows."""
        return catalog_runs()

    @mcp.tool(annotations=ToolAnnotations(readOnlyHint=True,destructiveHint=False,openWorldHint=False))
    def fm_query_observed_match_run(source_id:str,capture_id:str,table:str='fixtures',fields:list[str]|None=None,
                                   side_index:int|None=None,period:str|None=None,sort_by:str|None=None,
                                   descending:bool=False,limit:int=100,cursor:str|None=None) -> dict[str,Any]:
        """Query one explicitly pinned observed native run discovered by fm_list_observed_match_runs. For recorded tactical setup changes, use optional recorded_tactical_snapshots and recorded_tactical_changes when advertised. They return captured team instructions, mentality and phase roles with source hashes and capture timestamps. A verified recorder capture supplies one observation per side with exact cursor window, fixed event cursor separately, and raw instruction flags/unknown bits; period/score and change history stay unknown. Changes are available only where the catalog advertises independently attested before/after observations; a single sample supplies no before-state. Differences are bounded between sparse observations; the later snapshot may be deep into the second half, so never claim an exact halftime change time, kickoff setup, every intervening instruction or a causal effect. Current tactics cannot replace a missing recorded before-state. For score-versus-performance questions read fixtures, match_period_team_totals and shots; sort shots by expected_goals descending to choose an event to review. Use optional named_shot_chances when advertised to answer WHO made the recorded chances: shooter_name/shooter_person_native_id come from the checked original-slot roster and complete terminal source history. actor_state unresolved_original_slot keeps that shooter null; never fill it from the current lineup. Base shots.actor_name remains unchanged and unknown. Native shot event_id/outcome/body_part and raw clock fields identify recorded chances; raw clocks are not displayed minutes. A named shooter does not establish the chance supplier or assist. side_index0 is home and1 away; no filter returns both. Period xG is derived from captured attempts, not an official period counter. The optional completed_pass_event_locations view is independently derived from the pinned terminal raw events after every base event/actor/clock/period agrees. Use sender/receiver names or canonical IDs with native_event_x/y, attack_relative_longitudinal_coordinate and analytical_pitch_third/channel to analyze where a named pair linked up; these are pass-map EVENT points, not proved ball-release/reception/destination or trajectory. Physical units and human left/right remain unknown. If the catalog omits this optional view, its native-source attestation or source agreement is unavailable; base tables remain usable. Optional credited_assist_annotations reports natively credited-assist marked events only after every independent player Assists counter—including zeros—closes. It is distinct from generic shot supply: shot_event_id/goal_event_id stay null, same-clock adjacency is not ordering, and non-completed-event recipients remain unproved. Older retained copies can strip this flag; missing retained annotations are not zero assists. Base passing tables contain completed events only. Optional pass_attempt_events, when explicitly attested and advertised, contains native category7 completed and other6..11 not_completed EVENT map points excluding mask8. Query outcome, sender_name/ID, native_event_x/y and analytical thirds/channels to locate incomplete attempts. Their secondary bytes are not recipients; failure reason and possession-loss association are unknown. These points do not prove release/reception/intended destination, an independently reconciled attempts denominator or tactical cause. Older originals without captured XY or attestation remain unavailable for this view; spatial/heatmap rows carry their own earlier-prefix scope and are not terminal full-match positions. Optional exact named-period and side filters apply only to tables containing those fields. Request distinct catalog columns, optionally sort by one column; no caller SQL, filenames or paths. Up to200rows/128KiB, deterministic hash-pinned pages expire in5minutes; continue every next_cursor with identical selectors. Missing data is unknown, never zero. Raw source documents/private pointers, retained individual counters, actual shot minutes, causation and current player eligibility are not supplied. No game attachment, UI, game functions or writes."""
        return queries.query(source_id,capture_id,table,fields,side_index=side_index,period=period,
                             sort_by=sort_by,descending=descending,limit=limit,cursor=cursor)
